x-codeSamples.source:
curl -X POST \
  "https://www.sim.ai/api/v2/mcp-servers" \
  -H "X-API-Key: YOUR_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "workspaceId": "YOUR_WORKSPACE_ID",
    "name": "Docs server",
    "url": "https://mcp.example.com/sse",
    "headers": { "Authorization": "Bearer YOUR_TOKEN" }
  }'

curl -X POST \
  "https://www.sim.ai/api/v2/custom-tools" \
  -H "X-API-Key: YOUR_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "workspaceId": "YOUR_WORKSPACE_ID",
    "title": "lookup_order",
    "schema": {
      "type": "function",
      "function": {
        "name": "lookup_order",
        "parameters": {
          "type": "object",
          "properties": { "orderId": { "type": "string" } },
          "required": ["orderId"]
        }
      }
    },
    "code": "return { ok: true }"
  }'
